import psycopg2
import os
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time
import re

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'webapp')
DB_PASS = os.environ.get('DB_PASS', 'webapp_pass')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, database=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def rate_limit(f):
    """Basic rate limiting - 100 req/min per IP"""
    requests_log = {}
    @wraps(f)
    def decorated(*args, **kwargs):
        ip = request.remote_addr
        now = time.time()
        window = [t for t in requests_log.get(ip, []) if now - t < 60]
        if len(window) >= 100:
            return jsonify({'error': 'rate limited'}), 429
        requests_log[ip] = window + [now]
        return f(*args, **kwargs)
    return decorated

def sanitize_order(order_clause):
    """Attempt to sanitize ORDER BY - allows column names and direction"""
    # Only allow alphanumeric, underscore, space, comma, and ASC/DESC
    if re.match(r'^[a-zA-Z_,\s]+(ASC|DESC)?$', order_clause or ''):
        return order_clause
    return 'id ASC'

@app.route('/api/products/search', methods=['GET'])
@rate_limit
def search_products():
    """Search products with filtering and sorting"""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name ASC')
    page = int(request.args.get('page', '1'))
    per_page = min(int(request.args.get('per_page', '20')), 100)

    db = get_db()
    cur = db.cursor()

    # Build query with parameterized values for WHERE clause
    base_query = "SELECT id, name, description, price, category, stock_count FROM products"
    conditions = []
    params = []

    if category:
        conditions.append("category = %s")
        params.append(category)

    conditions.append("price >= %s")
    params.append(float(min_price))
    conditions.append("price <= %s")
    params.append(float(max_price))

    where_clause = " WHERE " + " AND ".join(conditions) if conditions else ""

    # Sort is sanitized via regex
    safe_sort = sanitize_order(sort_by)

    offset = (page - 1) * per_page

    query = f"{base_query}{where_clause} ORDER BY {safe_sort} LIMIT %s OFFSET %s"
    params.extend([per_page, offset])

    cur.execute(query, params)
    rows = cur.fetchall()

    products = []
    for row in rows:
        products.append({
            'id': row[0], 'name': row[1], 'description': row[2],
            'price': float(row[3]), 'category': row[4], 'stock': row[5]
        })

    return jsonify({'products': products, 'page': page})

@app.route('/api/products/<int:product_id>/reviews', methods=['GET'])
def get_reviews(product_id):
    """Get reviews for a product with optional filtering"""
    rating_filter = request.args.get('rating', '')
    author = request.args.get('author', '')

    db = get_db()
    cur = db.cursor()

    # Vulnerable: string formatting in query construction
    query = f"SELECT id, author, rating, comment, created_at FROM reviews WHERE product_id = {product_id}"

    if rating_filter:
        query += f" AND rating = {rating_filter}"

    if author:
        query += f" AND author = '{author}'"

    query += " ORDER BY created_at DESC LIMIT 50"

    cur.execute(query)
    rows = cur.fetchall()

    reviews = []
    for row in rows:
        reviews.append({
            'id': row[0], 'author': row[1], 'rating': row[2],
            'comment': row[3], 'created_at': str(row[4])
        })

    return jsonify({'reviews': reviews, 'product_id': product_id})

